package org.researchdock.mobile;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.text.Spanned;import android.text.style.BackgroundColorSpan;
import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class FullTextNavigationTest {
 private Object field(Object a,Class<?> type,String name)throws Exception{java.lang.reflect.Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private Button button(View v){if(v instanceof Button&&((Button)v).getText().toString().equals("阅读原文并定位"))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=button(((ViewGroup)v).getChildAt(i));if(b!=null)return b;}return null;}
 private boolean highlighted(View v){if(v instanceof TextView){CharSequence text=((TextView)v).getText();if(text.toString().contains("独有订单证据")&&text instanceof Spanned){Spanned s=(Spanned)text;for(BackgroundColorSpan span:s.getSpans(0,s.length(),BackgroundColorSpan.class))if(s.subSequence(s.getSpanStart(span),s.getSpanEnd(span)).toString().equals("独有订单证据"))return true;}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(highlighted(((ViewGroup)v).getChildAt(i)))return true;return false;}
 @Test public void cachedSourceHighlightsAndReturnsToSameSearchView()throws Exception{
  if(!"true".equals(InstrumentationRegistry.getArguments().getString("navigation_test")))return;
  Instrumentation inst=InstrumentationRegistry.getInstrumentation();Context context=inst.getTargetContext();MainActivity host=(MainActivity)inst.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<300&&(Boolean)field(host,MainActivity.class,"syncing");i++)Thread.sleep(100);
  String id="doc_"+"S".repeat(26);java.io.File file=new java.io.File(context.getFilesDir(),id+".json");assertFalse(file.exists());StringBuilder body=new StringBuilder("# 合成原文\n");for(int i=0;i<70;i++)body.append("这是前置段落，用于核实定位与返回，非真实研究内容。\n\n");body.append("😀这里的**独有订单证据**应被准确定位。\n");JSONObject source=new JSONObject().put("document_id",id).put("revision",1).put("title","合成搜索原文").put("body",body.toString());try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(source.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
  android.content.SharedPreferences prefs=context.getSharedPreferences("reader",Context.MODE_PRIVATE);String previous=prefs.getString("last_article","");SearchActivity search=null;MainActivity reader=null;Instrumentation.ActivityMonitor monitor=inst.addMonitor(SearchReaderActivity.class.getName(),null,false);
  try{search=(SearchActivity)inst.startActivitySync(new Intent(context,SearchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SearchActivity active=search;
   JSONObject metadata=new JSONObject(source.toString());metadata.remove("body");JSONObject row=new JSONObject().put("document",metadata).put("snippet","😀独有订单证据").put("match_start",1).put("match_end",7).put("match_field","body").put("cache",file.getName());JSONObject data=new JSONObject().put("scope","cloud_archived_text").put("offset_encoding","unicode_codepoints").put("results",new JSONArray().put(row));
   inst.runOnMainSync(()->{try{((EditText)field(active,SearchActivity.class,"input")).setText("独有订单证据");java.lang.reflect.Method render=SearchActivity.class.getDeclaredMethod("showResults",JSONObject.class,String.class,boolean.class);render.setAccessible(true);render.invoke(active,data,"独有订单证据",false);assertTrue(highlighted(active.getWindow().getDecorView()));Button open=button(active.getWindow().getDecorView());assertNotNull(open);open.performClick();}catch(Exception e){throw new RuntimeException(e);}});
   reader=(MainActivity)inst.waitForMonitorWithTimeout(monitor,15000);assertNotNull(reader);for(int i=0;i<300;i++){if(field(reader,MainActivity.class,"currentArticle")!=null&&!(Boolean)field(reader,MainActivity.class,"articleRenderPending"))break;Thread.sleep(50);}inst.waitForIdleSync();MainActivity shown=reader;
   inst.runOnMainSync(()->{try{assertTrue((Boolean)field(shown,MainActivity.class,"reading"));assertTrue(highlighted(shown.getWindow().getDecorView()));assertTrue(((ScrollView)field(shown,MainActivity.class,"scroll")).getScrollY()>0);shown.onBackPressed();}catch(Exception e){throw new RuntimeException(e);}});inst.waitForIdleSync();assertEquals("独有订单证据",((EditText)field(search,SearchActivity.class,"input")).getText().toString());assertNotNull(button(search.getWindow().getDecorView()));
  }finally{inst.removeMonitor(monitor);if(reader!=null){MainActivity end=reader;inst.runOnMainSync(end::finish);}if(search!=null){SearchActivity end=search;inst.runOnMainSync(end::finish);}inst.runOnMainSync(host::finish);file.delete();prefs.edit().putString("last_article",previous).remove("read:"+id).remove("progress:"+id+":r1").apply();}
 }
}
